const r = $input.first().json;
let t = r.output || r.text || r.response || '';
if (typeof t !== 'string') t = JSON.stringify(t);
t = t.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let p;
try {
  p = JSON.parse(t);
} catch (e) {
  const m = t.match(/\{[\s\S]*\}/);
  if (m) {
    try { p = JSON.parse(m[0]); } catch (e2) {}
  }
}
if (!p || typeof p !== 'object') throw new Error('AI çıktısı JSON olarak okunamadı: ' + t.substring(0, 500));

let brief = {};
try {
  brief = $('Mesaj Hazirla').first().json;
} catch (e) {
  try { brief = $items('Mesaj Hazirla')[0].json; } catch (e2) { brief = $input.first().json; }
}
const fallback = {
  nis: brief.nis || 'güzellik merkezleri',
  aci_nokta: brief.aci_nokta || 'DM ve randevu taleplerine geç dönüş yüzünden müşteri kaybı',
  icerik_fikri: brief.icerik_fikri || 'AI randevu asistanı ile kaçan talepleri görünür kılan premium içerik konsepti',
  visual_headline: brief.headline || 'RANDEVU KACAGI',
  visual_subline: brief.subline || 'DM taleplerini 7/24 yakala',
  caption: 'Ergene AI özel chatbotları ve otomasyon sistemleri, işletmenizin kaçırdığı talepleri 7/24 karşılar ve ekibinize düzenli akış sağlar.\n\nDetaylı bilgi için profildeki linkten Ergene AI ile iletişime geçin.\n\n#yapayzekaotomasyonu #ergeneai #chatbot #otomasyon #isletmeyonetimi',
  gorsel_yonu: 'Premium AI automation poster with niche-specific UI modules.',
  tasarim_notlari: 'Az metin kullan. Tek odak noktası ana başlık olsun. Küçük UI alanlarında kelime değil ikon, çizgi, dot ve checkmark kullan.',
  visual_modules: brief.visual_modules || '1. Chatbot message card with abstract message bubbles\n2. Booking or CRM card with check icons\n3. Simple growth chart or minimal automation flow'
};

const required = ['nis','aci_nokta','icerik_fikri','visual_headline','visual_subline','caption','gorsel_yonu','tasarim_notlari'];
for (const key of required) {
  if (typeof p[key] !== 'string' || !p[key].trim()) p[key] = fallback[key];
  p[key] = p[key].trim();
}

function asciiTR(value) {
  return String(value || '')
    .replace(/[çÇ]/g, 'c').replace(/[ğĞ]/g, 'g').replace(/[ıİ]/g, 'i')
    .replace(/[öÖ]/g, 'o').replace(/[şŞ]/g, 's').replace(/[üÜ]/g, 'u')
    .replace(/7\s*\/\s*24/g, '7/24')
    .replace(/\b724\b/g, '7/24')
    .replace(/[^a-zA-Z0-9 !?\/]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
function stripForbidden(value) {
  return String(value || '')
    .replace(/ergene\s*ai/gi, 'AI automation agency')
    .replace(/ergeneai\.com/gi, '')
    .replace(/website/gi, '')
    .replace(/watermark/gi, '')
    .replace(/hashtag/gi, '')
    .replace(/logo/gi, '')
    .trim();
}
function nicheHeadline(niche, pain) {
  const text = `${niche} ${pain}`.toLowerCase();
  if (text.includes('hukuk')) return 'TALEP KAYBI';
  if (text.includes('restoran')) return 'MASA KAYBI';
  if (text.includes('diş') || text.includes('dis') || text.includes('klinik') || text.includes('sağlık') || text.includes('saglik')) return 'HASTA DESTEGI';
  if (text.includes('emlak')) return 'LEAD KAYBI';
  if (text.includes('otel')) return 'REZERVASYON KAYBI';
  if (text.includes('e-ticaret') || text.includes('eticaret')) return 'SEPET KAYBI';
  if (text.includes('güzellik') || text.includes('guzellik') || text.includes('kuaför') || text.includes('kuafor')) return 'RANDEVU KACAGI';
  if (text.includes('muhasebe')) return 'EVRAK TAKIBI';
  if (text.includes('sigorta')) return 'TEKLIF KAYBI';
  if (text.includes('spor')) return 'UYE KAYBI';
  return fallback.visual_headline;
}
function cleanHeadline(value, niche, pain) {
  const raw = String(value || fallback.visual_headline);
  const risky = /%\s*100|100|yuzde|yüzde|garanti|kesin|memnuniyet|kontrol|kazan|arttir|artır|yonlendir|yönlendir/i.test(raw);
  let h = asciiTR(raw).toUpperCase();
  h = h.replace(/YUZDE\s*100/g, '').replace(/100/g, '').replace(/GARANTI/g, '').replace(/KESIN/g, '').trim();
  h = h.split(' ').slice(0, 3).join(' ').slice(0, 20).trim();
  if (risky || !h || h.length < 4 || h.split(' ').length > 3) h = nicheHeadline(niche, pain);
  return h;
}
function cleanSubline(value) {
  let s = asciiTR(value || fallback.visual_subline).replace(/\b724\b/g, '7/24');
  const risky = /memnuniyet|yonlend|yönlend|degisiklik|değişiklik|kazan|arttir|artır/i.test(String(value || ''));
  s = s.split(' ').slice(0, 5).join(' ').slice(0, 42).trim();
  if (risky || !s) s = fallback.visual_subline;
  return s;
}

const headline = cleanHeadline(p.visual_headline || fallback.visual_headline, p.nis, p.aci_nokta);
const subline = cleanSubline(p.visual_subline || fallback.visual_subline);
const direction = stripForbidden(p.gorsel_yonu);
const notes = stripForbidden(p.tasarim_notlari);
const visualModules = stripForbidden(brief.visual_modules || p.visual_modules || fallback.visual_modules);

const master_prompt = `Create a premium 1080x1080 Instagram square ad creative for a professional AI automation agency.

Context: ${p.nis}. Business problem: ${p.aci_nokta}. Creative idea: ${p.icerik_fikri}.

Visual style: matte black background, neon green #39FF14 accents, white typography, premium SaaS marketing aesthetic, Apple-like clean composition, modern B2B AI startup branding, high contrast, polished agency-quality finish. Use controlled glow, crisp edges, realistic premium lighting, and restrained contrast. Avoid cyberpunk clutter.

READABLE TEXT RULE - ABSOLUTE:
The image must contain exactly two readable text elements total, and no other words anywhere.
Text element 1, main headline: "${headline}"
Text element 2, supporting line: "${subline}"
Do not render any other readable text, even if words appear in this prompt as instructions.

Composition:
Create a clean niche-specific automation poster, not a generic dashboard. The niche must be obvious at first glance from the sector object, icon, or scene.
Use a strong poster layout: large headline in the upper-left area, one premium niche hero object or scene in the upper-right/background area, and three compact UI modules in the lower half.\nUse one clear focal point: a premium AI automation control panel that visually belongs to ${p.nis}. Make the sector signal stronger than the generic SaaS interface.\nKeep the UI modules slightly smaller than the headline and hero object, with generous negative space between modules.
Show exactly these 3 minimal visual modules. These module descriptions are instruction-only; never write their words or titles inside the image:
${visualModules}

Inside modules use only icons, grey/white placeholder bars, checkmarks, dots, arrows, subtle glow, niche symbols, abstract UI shapes.
No module titles, card labels, or copied words from these instructions.\nUse realistic premium hero objects when useful: car, house, hotel, table layout, clinic card, folder, product card, shield, school, gym equipment. Keep accent icons proportionate.\nSmall UI cards: prefer abstract thumbnails, silhouettes, icons, and placeholder lines.
Forbidden extra text: Checkout, E-commerce, Order, Support, Recovery, Demand, Capacity, Guests, Booking, CRM, Dashboard, Reservation, Status, Client, Lead, Sales, Product, random letters, English/Turkish words, numbers, fake UI labels.
Keep the layout spacious, minimal, premium, poster-like, and easy to understand in the first second.

Visual direction: ${direction}

Design rules:
Make it look like a professional Instagram agency creative, not a stock image.
Do not overcrowd the design.
Do not add logo, star mark, signature, neon wave, energy trail, lens flare, giant floating icon, oversized tag/pin, side crop artifact, extra words, brand/domain/site, watermark, hashtags, or paragraphs.
Use only the headline and supporting line above as readable text.
Keep every visible word ASCII Turkish and spell it exactly.
Final quality target: premium SaaS ad, strong niche recognition, fewer elements, more negative space, no clutter. Replace any extra readable word with a grey placeholder bar or icon.`;

const prompt_text = `MASTER PROMPT - KOPYALA
\`\`\`
${master_prompt}
\`\`\``;

const details_text = `CAPTION
${p.caption}

İÇERİK ÖZETİ
Niş: ${p.nis}
Acı nokta: ${p.aci_nokta}
Fikir: ${p.icerik_fikri}

TASARIM NOTLARI
${notes}`;

return [
  { json: { ...p, message_part: 'master_prompt', visual_headline_clean: headline, visual_subline_clean: subline, visual_modules: visualModules, master_prompt, telegram_text: prompt_text } },
  { json: { ...p, message_part: 'caption_details', visual_headline_clean: headline, visual_subline_clean: subline, visual_modules: visualModules, master_prompt, telegram_text: details_text } }
];
